# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: A simple yet effective (1+1)-Evolution Strategy with adaptive step-size control.
# Search state: Stores the current best solution (x) and the standard deviation (sigma) of the mutation distribution.
# Candidate generation: New candidates are generated by adding Gaussian noise to the current best solution.
# Selection and replacement: A greedy strategy; if the new candidate provides a lower objective value, it replaces the current best.
# Adaptation: Employs the 1/5-rule for step-size control (sigma) to keep the success rate near 20%.
# Exploration mechanisms: Gaussian mutation with adaptive sigma allows the algorithm to cover local and global scales.
# Exploitation mechanisms: The greedy selection process refines the solution locally in areas of improvement.
# Boundary handling: Candidates are clipped to the provided bounds using numpy.clip.
# Budget strategy: Iterates exactly until the remaining budget is consumed.
# Closest known influences: (1+1)-ES with self-adapting scale.
# Novelty or unusual aspects: Minimalist implementation focusing on robustness in black-box scenarios.
# Failure modes: Can get trapped in local optima for highly multi-modal functions.
# ALGORITHM_ANALYSIS_NOTE_END

import numpy as np

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        # Extract bounds
        if hasattr(func, 'lower') and hasattr(func, 'upper'):
            lb, ub = np.array(func.lower), np.array(func.upper)
        else:
            lb, ub = np.array(func.bounds.lb), np.array(func.bounds.ub)

        # Initialization: random starting point
        x = np.random.uniform(lb, ub)
        y = func(x)
        self.budget -= 1
        
        # Initial sigma as 1/6th of the search space width
        sigma = (ub - lb) / 6.0
        
        # Success tracking for 1/5-rule adaptation
        success_count = 0
        gen_count = 0
        
        # Optimization loop
        while self.budget > 0:
            # Mutation
            x_new = np.clip(x + np.random.normal(0, sigma), lb, ub)
            y_new = func(x_new)
            self.budget -= 1
            gen_count += 1
            
            # Greedy selection
            if y_new <= y:
                x = x_new
                y = y_new
                success_count += 1
                
            # Adapt sigma every 10 iterations using 1/5 success rule
            if gen_count >= 10:
                sr = success_count / gen_count
                if sr > 0.2:
                    sigma *= 1.2
                elif sr < 0.2:
                    sigma *= 0.8
                success_count = 0
                gen_count = 0
                
            # Early exit if budget is consumed
            if self.budget <= 0:
                break
                
        return x, y
